import {mountBike} from './bike-3d.mjs';
import {createShift,shiftState,shiftScore,shiftAct,shiftFaults} from './shift-model.mjs';
const $=s=>document.querySelector(s),storageKey='mecanica.bikes.shifting.v1';let s=createShift(),running=false,exploded=false,rows=[],warning='';try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(data))rows=data.filter(r=>r&&typeof r.id==='string'&&Number.isFinite(r.score)&&typeof r.date==='string').slice(-30);}catch{warning='No se pudo leer el historial.';}
const info={cassette:'Siete coronas. La corona resaltada corresponde a la posición más cercana de la guía. Una guía entre coronas indica mala alineación, no un engrane correcto.',chain:'La cadena cambia su línea lateral hacia el cassette. Se representa la trayectoria de forma esquemática; el cambio real necesita giro y contacto con los dientes.',derailleur:'La guía se desplaza con el mando y el tensor, hasta encontrar uno de los topes. Observa su posición respecto a la corona objetivo.',stops:'H (cabeza ámbar, izquierda) y L (cabeza verde, derecha) limitan extremos distintos. El giro visible representa pasos de ajuste; no equivale al sentido ni número de vueltas de tu componente.',frame:'Bicicleta completa sobre el banco. Acerca la transmisión para comprobar la línea de cadena.'};
const bench=mountBike($('#viewport'),focus);
function focus(id){if(!info[id])return;bench.select(id);bench.focus();$('#piece').textContent=info[id];}
function update(){const v=shiftState(s),position=v.position;bench.set({gear:v.teeth,cadence:24,faults:{},shift:{radius:.15+v.engaged*.03,chainZ:.7-position*.075,guideZ:.7-position*.075,h:s.h,l:s.l}});bench.play(running&&!v.unsafe);$('#play').textContent=running&&!v.unsafe?'Pausar transmisión':v.unsafe?'Ensayo pausado · fuera de rango':'Mover transmisión';$('#play').setAttribute('aria-pressed',String(running&&!v.unsafe));$('#shiftReadout').textContent=(s.test==='gear'?'Mando: marcha '+(s.requested+1):'Prueba de extremo '+s.test.toUpperCase())+' · Guía: posición '+(position+1).toFixed(2)+' / 7 · '+v.status;$('#score').textContent=shiftScore(s)+'/100';$('#feedback').textContent=s.feedback;$('#checks').textContent=['h','l',...Array.from({length:7},(_,i)=>'g'+i)].map(k=>(k[0]==='g'?+k.slice(1)+1:k.toUpperCase())+': '+(s.checks[k]===true?'✓':s.checks[k]===false?'✕':'pendiente')).join(' · ');for(const b of $('#gears').children){b.disabled=s.done;b.setAttribute('aria-pressed',String(s.test==='gear'&&+b.dataset.gear===s.requested));}for(const b of $('#adjustments').querySelectorAll('button'))b.disabled=s.done;for(const id of ['testH','testL','verify'])$('#'+id).disabled=s.done;$('#hint').disabled=s.done||s.hintUsed;
 for(const key of ['trim','h','l']){const original=s.initial[{trim:0,h:1,l:2}[key]],delta=Math.round((s[key]-original)*10);$('#delta-'+key).textContent='Cambio aplicado desde el inicio: '+(delta>=0?'+':'')+delta+' pasos';}
 if(s.done&&!rows.some(r=>r.id===s.id)){rows.push({id:s.id,date:new Date().toISOString(),score:shiftScore(s),mode:s.mode,errors:s.errors,hints:s.hints,causes:s.causes});rows=rows.slice(-30);try{localStorage.setItem(storageKey,JSON.stringify(rows));}catch{warning='El resultado solo se conserva en esta sesión.';}}
 $('#result').replaceChildren();if(s.done){add('h3','Caso resuelto', $('#result'));add('p','Causas iniciales: '+s.causes.map(k=>shiftFaults[k]).join(' · '),$('#result'));add('p','La solución separa topes e indexación: H y L alineados en los extremos, después tensión para las marchas intermedias. Otro orden puede funcionar si verificas todo al final.', $('#result'));}renderHistory();}
function act(action,key,value){shiftAct(s,action,key,value);update();}
function add(tag,text,root){const e=document.createElement(tag);e.textContent=text;root.append(e);return e;}
for(let i=0;i<7;i++){const b=add('button',String(i+1),$('#gears'));b.dataset.gear=i;b.setAttribute('aria-label','Seleccionar marcha '+(i+1));b.onclick=()=>act('select',null,i);}
const specs=[['trim','Tensor · indexación','Alinea las marchas intermedias. No modifica los topes físicos.','Reducir tensión','Aumentar tensión'],['h','Tope H · corona pequeña','Debe permitir llegar a la corona pequeña sin dejar salir la cadena hacia afuera.','Permitir más salida exterior','Limitar salida exterior'],['l','Tope L · corona grande','Debe permitir alcanzar la corona grande sin dejar pasar hacia los radios.','Limitar hacia los radios','Permitir más recorrido interior']];
for(const [key,title,copy,minus,plus]of specs){const card=add('div','',$('#adjustments'));card.className='adjustment';add('h3',title,card);add('p',copy,card);for(const [label,value]of [[minus,-1],[plus,1]]){const b=add('button',label,card);b.dataset.adjust=key;b.dataset.direction=value;b.onclick=()=>act('adjust',key,value);}const d=add('p','',card);d.id='delta-'+key;d.className='caption';}
function start(mode){s=createShift(mode);running=false;instructions();update();focus('cassette');}
function instructions(){const root=$('#instructions');root.replaceChildren();add('h2',s.mode==='guided'?'Taller guiado · topes e indexación':'Fallo sorpresa · mide antes de ajustar',root);if(s.mode==='guided'){const ol=add('ol','',root);ol.className='guided-steps';for(const t of ['Prueba H con el cable aislado y alinea la guía con la corona 1.','Prueba L y alinea el extremo interior con la corona 7.','Selecciona una marcha intermedia. Ajusta tensión en pequeños pasos para alinear la guía.','Recorre las siete marchas y repite H/L después del último ajuste.','Comprueba el trabajo completo y consulta las causas al terminar.'])add('li',t,ol);}else add('p','Puede fallar la tensión del cable o uno de los topes, por exceso o por defecto. Un extremo demasiado abierto puede parecer correcto al cambiar de marcha: comprueba también sus límites.',root);}
function renderHistory(){const root=$('#history');root.replaceChildren();add('h2','Tus prácticas de cambios',root);if(warning)add('p',warning,root);if(!rows.length)add('p','Los resultados aparecerán al completar la verificación. Se guardan hasta 30 casos en este navegador.',root);else{const ul=add('ul','',root);for(const r of rows.slice(-5).reverse())add('li',new Date(r.date).toLocaleDateString('es-CO')+' · '+(r.mode==='guided'?'Guiado':'Sorpresa')+' · '+r.score+'/100 · '+r.errors+' errores · '+r.hints+' pistas',ul);}}
$('#guided').onclick=()=>start('guided');$('#surprise').onclick=()=>start('surprise');$('#testH').onclick=()=>act('test','h');$('#testL').onclick=()=>act('test','l');$('#hint').onclick=()=>act('hint');$('#verify').onclick=()=>act('verify');$('#play').onclick=()=>{running=!running;update();};$('#explode').onclick=()=>{exploded=!exploded;bench.explode(exploded);$('#explode').setAttribute('aria-pressed',String(exploded));$('#explode').textContent=exploded?'Ensamblar':'Despiece';};$('#overview').onclick=()=>bench.reset();document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>focus(b.dataset.part));instructions();update();focus('cassette');window.shiftDebug=()=>({state:s,model:shiftState(s),bench:bench.debug?.(),history:rows});
